BEGIN;
CREATE TABLE IF NOT EXISTS buses (vehicle_number text PRIMARY KEY, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS routes (route_id text PRIMARY KEY, route_name text NOT NULL, first_stop text, last_stop text);
CREATE TABLE IF NOT EXISTS bus_route_pairs (vehicle_number text NOT NULL REFERENCES buses(vehicle_number), route_id text NOT NULL REFERENCES routes(route_id), source_timestamp timestamptz, PRIMARY KEY(vehicle_number,route_id));
CREATE TABLE IF NOT EXISTS drivers (driver_id text PRIMARY KEY, driver_name text);
CREATE TABLE IF NOT EXISTS conductors (conductor_id text PRIMARY KEY, conductor_name text);
CREATE TABLE IF NOT EXISTS service_assignments (assignment_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, service_date date NOT NULL, vehicle_number text NOT NULL REFERENCES buses(vehicle_number), route_id text NOT NULL REFERENCES routes(route_id), driver_id text REFERENCES drivers(driver_id), conductor_id text REFERENCES conductors(conductor_id), assignment_type text, UNIQUE(service_date,vehicle_number));
CREATE TABLE IF NOT EXISTS review_categories (category_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, category_name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS review_scenarios (scenario_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, category_id integer NOT NULL REFERENCES review_categories(category_id), scenario_name text NOT NULL, UNIQUE(category_id,scenario_name), UNIQUE(scenario_id,category_id));
CREATE TABLE IF NOT EXISTS reviews (review_id bigint PRIMARY KEY, assignment_id bigint REFERENCES service_assignments(assignment_id), scenario_id integer NOT NULL REFERENCES review_scenarios(scenario_id), review_text text NOT NULL, rating smallint CHECK(rating BETWEEN 1 AND 5), sentiment text CHECK(sentiment IN ('Positive','Negative','Neutral')), severity text, reviewed_at timestamp NOT NULL, time_of_day text, source_route_label text, source_dataset text, original_review_id bigint, source_is_negative boolean, source_negative_count numeric);
CREATE TABLE IF NOT EXISTS bus_locations (location_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, vehicle_number text NOT NULL REFERENCES buses(vehicle_number), route_id text REFERENCES routes(route_id), latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), observed_at timestamptz NOT NULL, collected_at timestamptz NOT NULL DEFAULT now(), UNIQUE(vehicle_number,observed_at));
CREATE INDEX IF NOT EXISTS idx_pairs_route ON bus_route_pairs(route_id);
CREATE INDEX IF NOT EXISTS idx_assignments_route_date ON service_assignments(route_id,service_date DESC);
CREATE INDEX IF NOT EXISTS idx_assignments_driver_date ON service_assignments(driver_id,service_date DESC);
CREATE INDEX IF NOT EXISTS idx_assignments_conductor_date ON service_assignments(conductor_id,service_date DESC);
CREATE INDEX IF NOT EXISTS idx_reviews_assignment ON reviews(assignment_id);
CREATE INDEX IF NOT EXISTS idx_reviews_scenario ON reviews(scenario_id);
CREATE INDEX IF NOT EXISTS idx_reviews_time ON reviews(reviewed_at DESC);
CREATE INDEX IF NOT EXISTS idx_locations_bus_time ON bus_locations(vehicle_number,observed_at DESC);
CREATE INDEX IF NOT EXISTS idx_locations_time ON bus_locations(observed_at DESC);
COMMIT;
